package dev.gbppimentel.zzz;
public final class SyncPolicyTest{public static void main(String[] args){SyncPolicy p=new SyncPolicy();if(!p.ready("notes",1000))throw new AssertionError();p.success("notes",1000,5000);if(p.ready("notes",5999)||!p.ready("notes",6000))throw new AssertionError();p.failure(6000,429,120000);if(p.allowed(125999)||!p.allowed(126000))throw new AssertionError();p.failure(126000,1034,0);if(p.allowed(Long.MAX_VALUE))throw new AssertionError();p.reconnect();if(!p.ready("notes",126001))throw new AssertionError();p.failure(1000,0,0);if(p.allowed(5999)||!p.allowed(6000))throw new AssertionError();if(SyncPolicy.retryAfter("120",0)!=120000||SyncPolicy.retryAfter("Thu, 01 Jan 1970 00:02:00 GMT",0)!=120000||SyncPolicy.retryAfter("garbage",0)!=0)throw new AssertionError();System.out.println("9 sync checks passed");}}
